import numpy as np

rng = np.random.RandomState(42)
raw_feature = rng.normal(loc=50000, scale=15000, size=10)  # simulating a raw income feature, in the thousands

def min_max_scale(x):
    return (x - x.min()) / (x.max() - x.min())

def standardize(x):
    return (x - x.mean()) / x.std()

min_max_scaled = min_max_scale(raw_feature)
standardized = standardize(raw_feature)

print("Raw feature:", np.round(raw_feature, 0))
print("Min-max scaled (0 to 1):", np.round(min_max_scaled, 3))
print("Standardized (mean 0, unit variance):", np.round(standardized, 3))
print(f"Standardized mean: {standardized.mean():.6f}, standardized std: {standardized.std():.6f}")
